/**
 * Enrichment & Missing States Script
 *
 * Generates missing jurisdiction data (ID, SC) and enriches existing statutes
 * with prosecution/defense strategic analysis.
 *
 * SAFETY: Case law is NEVER generated by this script. Case law MUST come from
 * verified sources (CourtListener API) via scripts/classify-case-law.mjs.
 * See .claude/rules/no-hallucinated-legal-data.md.
 *
 * Commands:
 *   npx tsx scripts/generate-case-law-enrichment.ts --missing-states                          # Generate ID + SC
 *   npx tsx scripts/generate-case-law-enrichment.ts --enrich --jurisdiction FL                 # Enrich single jurisdiction
 *   npx tsx scripts/generate-case-law-enrichment.ts --enrich --all                             # Enrich all jurisdictions
 *   npx tsx scripts/generate-case-law-enrichment.ts --full --all                               # Missing states + enrich all
 *   npx tsx scripts/generate-case-law-enrichment.ts --build-migration                          # Build SQL migration
 *   npx tsx scripts/generate-case-law-enrichment.ts --validate                                 # Validate output data
 *   npx tsx scripts/generate-case-law-enrichment.ts --stats                                    # Show statistics
 *   npx tsx scripts/generate-case-law-enrichment.ts --dry-run --enrich --jurisdiction FL       # Dry run
 *
 * Case law pipeline (VERIFIED SOURCES ONLY):
 *   node scripts/legal-research-all.mjs                                                        # Verify statutes
 *   node scripts/classify-case-law.mjs --limit 50                                              # Fetch+classify from CourtListener
 */

