interface JurisdictionStatute {
  common_charge_slug: string;
  statute_number: string;
  statute_title: string;
  offense_class: string;
  penalty_min: string | null;
  penalty_max: string;
  fine_max: string | null;
  elements: string[];
  mandatory_minimum: string | null;
  enhancements: string[];
  notes: string | null;
}

interface EnrichmentEntry {
  common_charge_slug: string;
  prosecution_strengths: string[];
  defense_opportunities: string[];
  common_defenses: string[];
}

// CaseLawEntry — read-only type for validation/stats of data produced by
// the VERIFIED pipeline (legal-research-all.mjs + classify-case-law.mjs).
// This script NEVER generates case law. See .claude/rules/no-hallucinated-legal-data.md.
interface CaseLawEntry {
  common_charge_slug: string;
  case_name: string;
  citation: string;
  court: string;
  year: number;
  holding: string;
  benefit_type: "prosecution" | "defense" | "both";
  significance: string;
}

