// ── Claude Code session (replaces direct Anthropic API) ────────────────────
// Uses callClaude subprocess wrapper: spawns `claude -p` under the local
// Claude Code session. Zero Anthropic API credits consumed.

async function callAnthropicAPI(
  prompt: string,
  _maxTokens: number = 16000
): Promise<string> {
  const result = await callClaude({ userPrompt: prompt });
  if (!result?.text) throw new Error("No text returned from claude -p");
  return result.text as string;
}


function stripMarkdownFences(raw: string): string {
  let s = raw.trim();
  if (s.startsWith("```")) {
    const firstNewline = s.indexOf("\n");
    const lastFence = s.lastIndexOf("```");
    if (firstNewline !== -1 && lastFence > firstNewline) {
      s = s.slice(firstNewline + 1, lastFence).trim();
    }
  }
  return s;
}

// ── File I/O ──────────────────────────────────────────────────────────────────

function ensureDir(dir: string): void {
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
}

function saveJSON(filepath: string, data: unknown): void {
  fs.writeFileSync(filepath, JSON.stringify(data, null, 2), "utf-8");
}

function loadJSON<T>(filepath: string): T {
  return JSON.parse(fs.readFileSync(filepath, "utf-8")) as T;
}

function jurisdictionFilePath(code: string): string {
  return path.join(DATA_DIR, `${code}.json`);
}

function enrichmentFilePath(code: string): string {
  return path.join(ENRICHMENT_DIR, `${code}.json`);
}

function caseLawFilePath(code: string): string {
  return path.join(CASE_LAW_DIR, `${code}.json`);
}

function delay(ms: number): Promise<void> {
  return new Promise<void>((resolve) => setTimeout(resolve, ms));
}

// ── SQL Escaping (split+join, no regex on content) ───────────────────────────

function escapeSqlSingleQuotes(val: string): string {
  return val.split("'").join("''");
}

function escapeSqlDoubleQuotes(val: string): string {
  return val.split('"').join('\\"');
}

function sqlStr(val: string | null): string {
  if (val === null || val === undefined) return "NULL";
  return "'" + escapeSqlSingleQuotes(val) + "'";
}

function sqlTextArray(arr: string[] | null | undefined): string {
  if (!arr || arr.length === 0) return "'{}'";
  const escaped = arr.map(
    (s) => '"' + escapeSqlDoubleQuotes(escapeSqlSingleQuotes(s)) + '"'
  );
  return "'{" + escaped.join(",") + "}'";
}

// ── Prompt Builders ───────────────────────────────────────────────────────────

function buildJurisdictionPrompt(code: string, name: string): string {
  const chargeList = COMMON_CHARGES.map(
    (c: CommonChargeDefinition) => `- ${c.slug}: ${c.label}`
  ).join("\n");

  return `You are a legal research assistant creating a criminal charge taxonomy database. For the jurisdiction of ${name} (${code}), provide the statute-specific information for each of the following common criminal charges.

For each charge, return a JSON object with:
- common_charge_slug: the slug from the list below
- statute_number: the specific statute number (e.g., "784.045" for FL, "PC 245(a)(1)" for CA)
- statute_title: official title of the statute
- offense_class: classification (e.g., "2nd Degree Felony", "Class A Misdemeanor")
- penalty_min: minimum penalty (e.g., "0 years" or null)
- penalty_max: maximum penalty (e.g., "15 years")
- fine_max: maximum fine (e.g., "$10,000")
- elements: array of prosecution elements (what must be proved)
- mandatory_minimum: specific mandatory minimum or null
- enhancements: array of applicable enhancements
- notes: jurisdiction-specific nuances (wobbler status, diversion eligibility, etc.)

OMIT any charge that does not exist as a distinct offense in this jurisdiction.

Return ONLY valid JSON — an array of objects. No markdown, no explanation.

Common charges to map:
${chargeList}`;
}

function buildEnrichmentPrompt(
  code: string,
  name: string,
  statutes: JurisdictionStatute[]
): string {
  const statuteList = statutes
    .map(
      (s) =>
        `- ${s.common_charge_slug}: ${s.statute_title} (${s.statute_number}) — ${s.offense_class}`
    )
    .join("\n");

  return `You are a criminal defense strategy analyst. For each statute in ${name} (${code}), provide a prosecution/defense benefit analysis.

For each statute below, return a JSON object with:
- common_charge_slug: the slug from the list
- prosecution_strengths: array of 3-5 typical prosecution advantages when bringing this charge (e.g., "Mandatory minimum limits plea bargaining leverage", "Multiple elements give prosecution charging flexibility")
- defense_opportunities: array of 3-5 strategic defense opportunities specific to this charge (e.g., "Elements require proving specific intent — creates reasonable doubt avenue", "Mandatory breath test challenge under implied consent statute")
- common_defenses: array of 3-5 recognized legal defenses for this charge (e.g., "Self-defense under § 776.012", "Lack of specific intent", "Entrapment")

Focus on ${name}-specific law, not generic defenses. Reference specific statutes, case law principles, and procedural rules where applicable. Each item should be a concise but specific statement (1-2 sentences max).

Return ONLY valid JSON — an array of objects. No markdown, no explanation.

Statutes to analyze:
${statuteList}`;
}

// ── Missing States ───────────────────────────────────────────────────────────

async function generateMissingStates(dryRun: boolean): Promise<void> {
  ensureDir(DATA_DIR);

  const toGenerate = MISSING_STATES.filter((code) => {
    const filepath = jurisdictionFilePath(code);
    if (fs.existsSync(filepath)) {
      console.log(`Skipping ${code} — JSON already exists`);
      return false;
    }
    return true;
  });

  if (toGenerate.length === 0) {
    console.log("All missing states already generated.");
    return;
  }

  console.log(
    `Generating ${toGenerate.length} missing state(s): ${toGenerate.join(", ")}`
  );

  for (let i = 0; i < toGenerate.length; i++) {
    const code = toGenerate[i];
    const jur = JURISDICTIONS.find((j) => j.code === code);
    if (!jur) {
      console.error(`Unknown jurisdiction code: ${code}`);
      continue;
    }

    console.log(`\nGenerating ${code} (${jur.name})... (${i + 1}/${toGenerate.length})`);
    const prompt = buildJurisdictionPrompt(jur.code, jur.name);

    if (dryRun) {
      console.log("\n--- DRY RUN: Prompt Preview ---");
      const preview =
        prompt.length > 2000
          ? prompt.slice(0, 2000) + `\n... [${prompt.length - 2000} more chars]`
          : prompt;
      console.log(preview);
      console.log(`\nTotal charges in prompt: ${COMMON_CHARGES.length}`);
      console.log("--- End of Prompt ---\n");
      continue;
    }

    try {
      const raw = await callAnthropicAPI(prompt);
      const jsonStr = stripMarkdownFences(raw);
      const parsed = JSON.parse(jsonStr) as JurisdictionStatute[];
      saveJSON(jurisdictionFilePath(code), parsed);
      console.log(`  Saved ${parsed.length} statutes for ${code}`);
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      console.error(`  ERROR generating ${code}: ${message}`);
    }

    if (!dryRun && i < toGenerate.length - 1) {
      await delay(2000);
    }
  }

  console.log("\nMissing states generation complete.");
}

// ── Enrichment ───────────────────────────────────────────────────────────────

async function enrichJurisdiction(
  code: string,
  name: string,
  index: number,
  total: number,
  dryRun: boolean
): Promise<void> {
  console.log(`Enriching ${code} (${name})... (${index}/${total})`);

  const statutePath = jurisdictionFilePath(code);
  if (!fs.existsSync(statutePath)) {
    console.error(`  Skipping ${code} — no statute data at ${statutePath}`);
    return;
  }

  const statutes = loadJSON<JurisdictionStatute[]>(statutePath);
  if (!Array.isArray(statutes) || statutes.length === 0) {
    console.error(`  Skipping ${code} — empty or invalid statute data`);
    return;
  }

  // Process in batches of 25 to keep prompt size manageable
  const BATCH_SIZE = 25;
  const allEnrichments: EnrichmentEntry[] = [];

  for (let batchIdx = 0; batchIdx < statutes.length; batchIdx += BATCH_SIZE) {
    const batch = statutes.slice(batchIdx, batchIdx + BATCH_SIZE);
    const batchNum = Math.floor(batchIdx / BATCH_SIZE) + 1;
    const totalBatches = Math.ceil(statutes.length / BATCH_SIZE);

    if (totalBatches > 1) {
      console.log(
        `  Batch ${batchNum}/${totalBatches} (${batch.length} statutes)`
      );
    }

    const prompt = buildEnrichmentPrompt(code, name, batch);

    if (dryRun) {
      if (batchIdx === 0) {
        console.log("\n--- DRY RUN: Enrichment Prompt Preview ---");
        const preview =
          prompt.length > 2000
            ? prompt.slice(0, 2000) +
              `\n... [${prompt.length - 2000} more chars]`
            : prompt;
        console.log(preview);
        console.log(`\nStatutes in batch: ${batch.length}`);
        console.log("--- End of Prompt ---\n");
      }
      continue;
    }

    try {
      const raw = await callAnthropicAPI(prompt);
      const jsonStr = stripMarkdownFences(raw);
      const parsed = JSON.parse(jsonStr) as EnrichmentEntry[];
      allEnrichments.push(...parsed);
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      console.error(
        `  ERROR enriching ${code} batch ${batchNum}: ${message}`
      );
    }

    if (!dryRun && batchIdx + BATCH_SIZE < statutes.length) {
      await delay(2000);
    }
  }

  if (!dryRun && allEnrichments.length > 0) {
    ensureDir(ENRICHMENT_DIR);
    saveJSON(enrichmentFilePath(code), allEnrichments);
    console.log(`  Saved ${allEnrichments.length} enrichment entries for ${code}`);
  }
}

async function enrichAll(dryRun: boolean): Promise<void> {
  const toProcess = JURISDICTIONS.filter(({ code }) => {
    const filepath = enrichmentFilePath(code);
    if (fs.existsSync(filepath)) {
      console.log(`Skipping ${code} enrichment — already exists`);
      return false;
    }
    // Must have statute data to enrich
    if (!fs.existsSync(jurisdictionFilePath(code))) {
      console.log(`Skipping ${code} enrichment — no statute data`);
      return false;
    }
    return true;
  });

  console.log(
    `\n${toProcess.length} jurisdictions to enrich (${JURISDICTIONS.length - toProcess.length} skipped)`
  );

  for (let i = 0; i < toProcess.length; i++) {
    const { code, name } = toProcess[i];
    await enrichJurisdiction(code, name, i + 1, toProcess.length, dryRun);
    if (!dryRun && i < toProcess.length - 1) {
      await delay(2000);
    }
  }

  console.log("\nEnrichment complete.");
}

async function enrichSingle(
  jurisdictionCode: string,
  dryRun: boolean
): Promise<void> {
  const upper = jurisdictionCode.toUpperCase();
  const jur =
    JURISDICTIONS.find((j) => j.code === upper) ??
    JURISDICTIONS.find(
      (j) => j.code.toLowerCase() === jurisdictionCode.toLowerCase()
    );

  if (!jur) {
    console.error(`Unknown jurisdiction: ${jurisdictionCode}`);
    console.error(
      `Valid codes: ${JURISDICTIONS.map((j) => j.code).join(", ")}`
    );
    process.exit(1);
  }

  ensureDir(ENRICHMENT_DIR);
  await enrichJurisdiction(jur.code, jur.name, 1, 1, dryRun);
}

