// See .claude/rules/no-hallucinated-legal-data.md

// ── Build Migration ──────────────────────────────────────────────────────────

function buildMigration(): void {
  const migrationDir = path.join(PROJECT_ROOT, "supabase", "migrations");
  ensureDir(migrationDir);

  // Find next migration number
  const existingMigrations = fs
    .readdirSync(migrationDir)
    .filter((f) => f.endsWith(".sql"))
    .sort();
  const lastMigration = existingMigrations[existingMigrations.length - 1];
  const lastNum = lastMigration
    ? parseInt(lastMigration.split("_")[0], 10)
    : 30;
  const nextNum = String(lastNum + 1).padStart(
    lastMigration ? lastMigration.split("_")[0].length : 16,
    "0"
  );

  const migrationFile = path.join(
    migrationDir,
    `${nextNum}_enrichment-and-case-law-data.sql`
  );

  const lines: string[] = [];

  lines.push(
    `-- Migration: Add enrichment columns to jurisdiction_statutes + benefit_type to statute_case_law`
  );
  lines.push(`-- Generated by scripts/generate-case-law-enrichment.ts`);
  lines.push(`-- Date: ${new Date().toISOString().split("T")[0]}`);
  lines.push("");

  // ── Part 1: Schema changes
  lines.push(
    "-- ============================================================"
  );
  lines.push(
    "-- 1. Add enrichment columns to jurisdiction_statutes"
  );
  lines.push(
    "-- ============================================================"
  );
  lines.push("");
  lines.push("ALTER TABLE jurisdiction_statutes");
  lines.push(
    "  ADD COLUMN IF NOT EXISTS prosecution_strengths text[] DEFAULT '{}',"
  );
  lines.push(
    "  ADD COLUMN IF NOT EXISTS defense_opportunities text[] DEFAULT '{}',"
  );
  lines.push(
    "  ADD COLUMN IF NOT EXISTS common_defenses text[] DEFAULT '{}';"
  );
  lines.push("");

  // ── Part 1b: Add benefit_type to statute_case_law
  lines.push(
    "-- ============================================================"
  );
  lines.push(
    "-- 2. Add benefit_type column to statute_case_law"
  );
  lines.push(
    "-- ============================================================"
  );
  lines.push("");
  lines.push("ALTER TABLE statute_case_law");
  lines.push(
    "  ADD COLUMN IF NOT EXISTS benefit_type text DEFAULT 'both';"
  );
  lines.push("");

  // ── Part 2: Enrichment data UPDATEs
  lines.push(
    "-- ============================================================"
  );
  lines.push(
    "-- 3. Enrichment data (prosecution/defense analysis)"
  );
  lines.push(
    "-- ============================================================"
  );
  lines.push("");

  let enrichmentCount = 0;
  for (const { code } of JURISDICTIONS) {
    const filepath = enrichmentFilePath(code);
    if (!fs.existsSync(filepath)) continue;

    let entries: EnrichmentEntry[];
    try {
      entries = loadJSON<EnrichmentEntry[]>(filepath);
    } catch {
      console.error(`  Skipping enrichment for ${code} — invalid JSON`);
      continue;
    }

    if (!Array.isArray(entries) || entries.length === 0) continue;

    lines.push(`-- ${code} enrichment`);
    for (const entry of entries) {
      const prosArr = sqlTextArray(entry.prosecution_strengths);
      const defOppArr = sqlTextArray(entry.defense_opportunities);
      const defArr = sqlTextArray(entry.common_defenses);

      lines.push(`UPDATE jurisdiction_statutes SET`);
      lines.push(`  prosecution_strengths = ${prosArr},`);
      lines.push(`  defense_opportunities = ${defOppArr},`);
      lines.push(`  common_defenses = ${defArr}`);
      lines.push(
        `WHERE common_charge_slug = ${sqlStr(entry.common_charge_slug)} AND jurisdiction = ${sqlStr(code)};`
      );
      lines.push("");
      enrichmentCount++;
    }
  }

  // ── Part 3: NO CASE LAW INSERTS ──
  // SAFETY: Case law is NEVER inserted from local files. Per the
  // no-hallucinated-legal-data rule, case law must come from CourtListener
  // via legal-research-all.mjs + classify-case-law.mjs. This script writes
  // ONLY enrichment (prosecution/defense strategic analysis) — never citations.
  lines.push(
    "-- ============================================================"
  );
  lines.push(
    "-- 4. Case law: NOT INSERTED HERE"
  );
  lines.push(
    "-- ============================================================"
  );
  lines.push("-- Case law comes ONLY from verified CourtListener sources via:");
  lines.push("--   node scripts/legal-research-all.mjs");
  lines.push("--   node scripts/classify-case-law.mjs");
  lines.push("-- See .claude/rules/no-hallucinated-legal-data.md");
  lines.push("");

  const sql = lines.join("\n");
  fs.writeFileSync(migrationFile, sql, "utf-8");

  console.log(`\nMigration written to: ${migrationFile}`);
  console.log(`  Enrichment UPDATEs : ${enrichmentCount}`);
  console.log(`  Case law INSERTs   : 0 (safety: verified sources only)`);
}

// ── Validation ───────────────────────────────────────────────────────────────

function validateOutput(): void {
  let totalErrors = 0;

  console.log("=== Validating Statute Data ===\n");

  const missingStatutes: string[] = [];
  for (const { code } of JURISDICTIONS) {
    if (!fs.existsSync(jurisdictionFilePath(code))) {
      missingStatutes.push(code);
    }
  }
  if (missingStatutes.length > 0) {
    console.log(
      `  Missing statute files: ${missingStatutes.join(", ")}`
    );
    totalErrors += missingStatutes.length;
  } else {
    console.log("  All 52 jurisdiction statute files present.");
  }

  console.log("\n=== Validating Enrichment Data ===\n");

  const ENRICHMENT_FIELDS: ReadonlyArray<keyof EnrichmentEntry> = [
    "prosecution_strengths",
    "defense_opportunities",
    "common_defenses",
  ];

  let enrichmentFiles = 0;
  let enrichmentEntries = 0;
  let enrichmentErrors = 0;

  for (const { code } of JURISDICTIONS) {
    const filepath = enrichmentFilePath(code);
    if (!fs.existsSync(filepath)) continue;

    enrichmentFiles++;
    let entries: EnrichmentEntry[];
    try {
      entries = loadJSON<EnrichmentEntry[]>(filepath);
    } catch {
      console.error(`  ${code}: INVALID JSON in enrichment file`);
      enrichmentErrors++;
      continue;
    }

    if (!Array.isArray(entries)) {
      console.error(`  ${code}: Enrichment data is not an array`);
      enrichmentErrors++;
      continue;
    }

    enrichmentEntries += entries.length;

    for (const entry of entries) {
      for (const field of ENRICHMENT_FIELDS) {
        const val = entry[field];
        if (!Array.isArray(val) || val.length === 0) {
          console.error(
            `  ${code}/${entry.common_charge_slug}: Empty ${field}`
          );
          enrichmentErrors++;
        }
      }
    }
  }

  console.log(`  Enrichment files   : ${enrichmentFiles}/52`);
  console.log(`  Enrichment entries : ${enrichmentEntries}`);
  console.log(`  Enrichment errors  : ${enrichmentErrors}`);
  totalErrors += enrichmentErrors;

  console.log("\n=== Validating Case Law Data ===\n");

  const CASE_LAW_REQUIRED: ReadonlyArray<keyof CaseLawEntry> = [
    "case_name",
    "citation",
    "court",
    "year",
    "holding",
    "benefit_type",
    "significance",
  ];

  let caseLawFiles = 0;
  let caseLawEntries = 0;
  let caseLawErrors = 0;

  for (const { code } of JURISDICTIONS) {
    const filepath = caseLawFilePath(code);
    if (!fs.existsSync(filepath)) continue;

    caseLawFiles++;
    let entries: CaseLawEntry[];
    try {
      entries = loadJSON<CaseLawEntry[]>(filepath);
    } catch {
      console.error(`  ${code}: INVALID JSON in case law file`);
      caseLawErrors++;
      continue;
    }

    if (!Array.isArray(entries)) {
      console.error(`  ${code}: Case law data is not an array`);
      caseLawErrors++;
      continue;
    }

    caseLawEntries += entries.length;

    // Check coverage: each statute should have 3-5 cases
    const statutePath = jurisdictionFilePath(code);
    if (fs.existsSync(statutePath)) {
      const statutes = loadJSON<JurisdictionStatute[]>(statutePath);
      const casesBySlug = new Map<string, number>();
      for (const e of entries) {
        casesBySlug.set(
          e.common_charge_slug,
          (casesBySlug.get(e.common_charge_slug) ?? 0) + 1
        );
      }
      for (const s of statutes) {
        const count = casesBySlug.get(s.common_charge_slug) ?? 0;
        if (count === 0) {
          console.error(
            `  ${code}/${s.common_charge_slug}: No case law entries`
          );
          caseLawErrors++;
        }
      }
    }

    for (const entry of entries) {
      for (const field of CASE_LAW_REQUIRED) {
        const val = entry[field];
        if (val === null || val === undefined || val === "") {
          console.error(
            `  ${code}/${entry.common_charge_slug}: Missing ${field} in "${entry.case_name || "unknown"}"`
          );
          caseLawErrors++;
        }
      }

      if (
        entry.benefit_type &&
        !["prosecution", "defense", "both"].includes(entry.benefit_type)
      ) {
        console.error(
          `  ${code}/${entry.common_charge_slug}: Invalid benefit_type "${entry.benefit_type}" in "${entry.case_name}"`
        );
        caseLawErrors++;
      }
    }
  }

  console.log(`  Case law files     : ${caseLawFiles}/52`);
  console.log(`  Case law entries   : ${caseLawEntries}`);
  console.log(`  Case law errors    : ${caseLawErrors}`);
  totalErrors += caseLawErrors;

  console.log(`\n=== Validation Summary ===`);
  console.log(`  Total errors: ${totalErrors}`);

  if (totalErrors > 0) process.exit(1);
}

// ── Stats ────────────────────────────────────────────────────────────────────

function showStats(): void {
  console.log("=== Charge Taxonomy Statistics ===\n");

  // Statutes
  let totalStatutes = 0;
  let statuteFiles = 0;
  const statuteCoverage: Array<{ code: string; count: number }> = [];

  for (const { code } of JURISDICTIONS) {
    const filepath = jurisdictionFilePath(code);
    if (!fs.existsSync(filepath)) continue;
    statuteFiles++;
    try {
      const data = loadJSON<JurisdictionStatute[]>(filepath);
      totalStatutes += data.length;
      statuteCoverage.push({ code, count: data.length });
    } catch {
      /* skip invalid */
    }
  }

  console.log(`Statute Data:`);
  console.log(`  Jurisdictions with data : ${statuteFiles}/52`);
  console.log(`  Total statutes          : ${totalStatutes}`);
  if (statuteCoverage.length > 0) {
    const avg = Math.round(totalStatutes / statuteCoverage.length);
    const min = Math.min(...statuteCoverage.map((s) => s.count));
    const max = Math.max(...statuteCoverage.map((s) => s.count));
    console.log(`  Avg per jurisdiction    : ${avg}`);
    console.log(`  Min                     : ${min}`);
    console.log(`  Max                     : ${max}`);
  }

  // Missing
  const missingStatutes = JURISDICTIONS.filter(
    ({ code }) => !fs.existsSync(jurisdictionFilePath(code))
  ).map(({ code }) => code);
  if (missingStatutes.length > 0) {
    console.log(`  Missing                 : ${missingStatutes.join(", ")}`);
  }

  // Enrichment
  let totalEnrichment = 0;
  let enrichmentFilesCount = 0;

  for (const { code } of JURISDICTIONS) {
    const filepath = enrichmentFilePath(code);
    if (!fs.existsSync(filepath)) continue;
    enrichmentFilesCount++;
    try {
      const data = loadJSON<EnrichmentEntry[]>(filepath);
      totalEnrichment += data.length;
    } catch {
      /* skip */
    }
  }

  console.log(`\nEnrichment Data:`);
  console.log(`  Jurisdictions enriched  : ${enrichmentFilesCount}/52`);
  console.log(`  Total enrichment entries: ${totalEnrichment}`);

  // Case Law
  let totalCaseLaw = 0;
  let caseLawFileCount = 0;
  let prosecutionCount = 0;
  let defenseCount = 0;
  let bothCount = 0;

  for (const { code } of JURISDICTIONS) {
    const filepath = caseLawFilePath(code);
    if (!fs.existsSync(filepath)) continue;
    caseLawFileCount++;
    try {
      const data = loadJSON<CaseLawEntry[]>(filepath);
      totalCaseLaw += data.length;
      for (const entry of data) {
        if (entry.benefit_type === "prosecution") prosecutionCount++;
        else if (entry.benefit_type === "defense") defenseCount++;
        else bothCount++;
      }
    } catch {
      /* skip */
    }
  }

  console.log(`\nCase Law Data:`);
  console.log(`  Jurisdictions with cases: ${caseLawFileCount}/52`);
  console.log(`  Total case law entries  : ${totalCaseLaw}`);
  if (caseLawFileCount > 0) {
    console.log(`  WARNING: case-law/ should be empty — case law belongs in DB only.`);
    console.log(`  Files here may be hallucinated. Run the watcher and delete.`);
  }

  // Estimated totals at completion
  console.log(`\nProjected at Full Completion:`);
  const avgStatutesPerJur =
    statuteCoverage.length > 0
      ? Math.round(totalStatutes / statuteCoverage.length)
      : 80;
  console.log(
    `  Est. total statutes     : ~${52 * avgStatutesPerJur}`
  );
  console.log(
    `  Est. enrichment entries : ~${52 * avgStatutesPerJur}`
  );
  console.log(
    `  Case law entries        : populated by legal-research-all.mjs (CourtListener), not this script`
  );
}

// ── CLI ──────────────────────────────────────────────────────────────────────

async function main(): Promise<void> {
  const args = process.argv.slice(2);
  const hasFlag = (flag: string): boolean => args.includes(flag);
  const getFlagValue = (flag: string): string | null => {
    const idx = args.indexOf(flag);
    return idx !== -1 && idx + 1 < args.length ? (args[idx + 1] ?? null) : null;
  };

  const dryRun = hasFlag("--dry-run");
  const jurisdictionCode = getFlagValue("--jurisdiction");
  const all = hasFlag("--all");

  if (hasFlag("--stats")) {
    showStats();
    return;
  }

  if (hasFlag("--validate")) {
    validateOutput();
    return;
  }

  if (hasFlag("--build-migration")) {
    buildMigration();
    return;
  }

  if (hasFlag("--missing-states")) {
    await generateMissingStates(dryRun);
    return;
  }

  if (hasFlag("--enrich")) {
    if (all) {
      await enrichAll(dryRun);
    } else if (jurisdictionCode) {
      await enrichSingle(jurisdictionCode, dryRun);
    } else {
      console.error("--enrich requires --all or --jurisdiction <CODE>");
      process.exit(1);
    }
    return;
  }

  if (hasFlag("--case-law")) {
    console.log("SAFETY: Case law is NEVER generated by this script.");
    console.log("Case law MUST come from verified sources (CourtListener API).\n");
    console.log("Use the verified pipeline instead:");
    console.log("  node scripts/legal-research-all.mjs          # Verify statutes + find citing cases");
    console.log("  node scripts/classify-case-law.mjs --limit 50 # Fetch+classify real opinions\n");
    console.log("See .claude/rules/no-hallucinated-legal-data.md");
    process.exit(1);
  }

  if (hasFlag("--full")) {
    if (!all && !jurisdictionCode) {
      console.error("--full requires --all or --jurisdiction <CODE>");
      process.exit(1);
    }

    if (all) {
      console.log("=== FULL RUN: All jurisdictions ===\n");
      console.log("Step 1/2: Missing states...");
      await generateMissingStates(dryRun);
      console.log("\nStep 2/2: Enrichment...");
      await enrichAll(dryRun);
    } else if (jurisdictionCode) {
      console.log(`=== FULL RUN: ${jurisdictionCode} ===\n`);

      const upper = jurisdictionCode.toUpperCase();
      if (MISSING_STATES.includes(upper)) {
        console.log("Step 1/2: Generate missing statute data...");
        await generateMissingStates(dryRun);
      } else {
        console.log("Step 1/2: Statute data already exists — skipping.");
      }

      console.log("\nStep 2/2: Enrichment...");
      await enrichSingle(jurisdictionCode, dryRun);
    }

    if (!dryRun) {
      console.log("\n=== Full run complete. Run --build-migration to create SQL. ===");
      console.log("For case law: node scripts/legal-research-all.mjs + node scripts/classify-case-law.mjs");
    }
    return;
  }

  // Default: usage
  console.log(`
Case Law Enrichment Script
============================
Usage:

  Missing States (ID, SC):
    npx tsx scripts/generate-case-law-enrichment.ts --missing-states
    npx tsx scripts/generate-case-law-enrichment.ts --dry-run --missing-states

  Enrichment (prosecution/defense analysis):
    npx tsx scripts/generate-case-law-enrichment.ts --enrich --jurisdiction FL
    npx tsx scripts/generate-case-law-enrichment.ts --enrich --all

  Case Law (VERIFIED SOURCES ONLY — never generated):
    node scripts/legal-research-all.mjs          # Verify statutes + find citing cases on CourtListener
    node scripts/classify-case-law.mjs --limit 50 # Fetch+classify real opinions from CourtListener

  Full Pipeline (missing states + enrichment only):
    npx tsx scripts/generate-case-law-enrichment.ts --full --all
    npx tsx scripts/generate-case-law-enrichment.ts --full --jurisdiction FL

  Build Migration:
    npx tsx scripts/generate-case-law-enrichment.ts --build-migration

  Validate & Stats:
    npx tsx scripts/generate-case-law-enrichment.ts --validate
    npx tsx scripts/generate-case-law-enrichment.ts --stats

  All commands support --dry-run to preview prompts without API calls.

Stats:
  Common charges    : ${COMMON_CHARGES.length}
  Jurisdictions     : ${JURISDICTIONS.length}
  Missing states    : ${MISSING_STATES.join(", ")}
  Output dirs       : data/charge-taxonomy/enrichment/
                      data/charge-taxonomy/case-law/
`);
}

main().catch((err: unknown) => {
  console.error("Fatal error:", err);
  process.exit(1);
});
